mapper.select:
SELECT COUNT(tot.*) FROM (SELECT EGBR.ROUTE_TY , /*EGBUCI.CLCT_YMD ,*/ EGBUCI.CO_NM, /*EGBUCI.CARD_APPR_TYPE ,*/ EGBR.ROUTE_ID, EGBR.EB_ROUTE_ID, EGBUCI.BUS_ROUTE_NO FROM BIGDATA.EXT_GBMS_BUS_USE_CALC_INFO EGBUCI INNER JOIN ( SELECT DISTINCT ON (ROUTE_ID) EGBR.ROUTE_ID ,EGBR.ROUTE_TY ,EBINFO.EB_ROUTE_ID FROM BIGDATA.EXT_GBMS_ROUTE EGBR INNER JOIN ( SELECT EGAP.ROUTE_ID AS ORG_ROUTE_ID, EGAP.EB_ROUTE_ID FROM BIGDATA.EXT_GGBIS_ALLOCATION_PLAN EGAP GROUP BY EGAP.ROUTE_ID, EGAP.EB_ROUTE_ID ) EBINFO ON EGBR.ROUTE_ID = EBINFO.ORG_ROUTE_ID ) EGBR ON EGBUCI.BUS_ROUTE_ID = EGBR.EB_ROUTE_ID
AND TO_CHAR(TO_DATE(EGBUCI.CLCT_YMD,'YYYYMMDD'), 'YYYY') = #{searchYear}
AND TO_CHAR(TO_DATE(EGBUCI.CLCT_YMD,'YYYYMMDD'), 'D') BETWEEN '2' AND '6'
AND TO_CHAR(TO_DATE(EGBUCI.CLCT_YMD,'YYYYMMDD'), 'D') = '1' OR TO_CHAR(TO_DATE(EGBUCI.CLCT_YMD,'YYYYMMDD'), 'D') = '7'
AND TO_CHAR(TO_DATE(EGBUCI.CLCT_YMD,'YYYYMMDD'), 'YYYY-MM-DD') BETWEEN #{startDate} AND #{endDate}
GROUP BY EGBR.ROUTE_TY , /*EGBUCI.CLCT_YMD ,*/ EGBUCI.CO_NM, /*EGBUCI.CARD_APPR_TYPE ,*/ EGBR.ROUTE_ID, EGBR.EB_ROUTE_ID, EGBUCI.BUS_ROUTE_NO ) tot
